from typing import List

def biGraph(n: int, e: int, arr: List[int]) -> int:
    def dfs(u, parent, low, disc, ap, time):
        nonlocal articulation_points, adj
        children = 0
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if disc[v] == -1:
                children += 1
                dfs(v, u, low, disc, ap, time)
                low[u] = min(low[u], low[v])

                if parent != -1 and low[v] >= disc[u]:
                    ap[u] = True
            elif v != parent:
                low[u] = min(low[u], disc[v])

        if parent == -1 and children > 1:
            ap[u] = True

    adj = [[] for _ in range(n)]
    for i in range(0, 2*e, 2):
        u, v = arr[i], arr[i+1]
        adj[u].append(v)
        adj[v].append(u)

    articulation_points = [False] * n
    disc = [-1] * n
    low = [-1] * n
    time = 0

    for i in range(n):
        if disc[i] == -1:
            dfs(i, -1, low, disc, articulation_points, time)

    return 1 if sum(articulation_points) == 0 and e >= n else 0
